head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF50000";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — loginYn

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_loginYn", fn: function(){ return ((dma_pageContext.get("loginYn") ?? "") === 'Y'); } }, { id: "if_loginYn_2", fn: function(){ return ((dma_pageContext.get("loginYn") ?? "") === 'N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 3개다(tx_goSearch, tx_goSearch2, tx_goView) — 어느 것이 «열자마자» 인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":1
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf50000' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf50000.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_goSearch
 * @description go Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch = async function () {
    const sbmOptions = {
        id: "tx_goSearch",
        method: "post",
        action: "/info/notice.do?method=noticeList",
        ref: "dma_goSearchReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goSearch2
 * @description go Search2 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goSearch2 = async function () {
    const sbmOptions = {
        id: "tx_goSearch2",
        method: "post",
        action: "/info/notice.do?method=noticeList",
        ref: "dma_goSearch2Req",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_goView
 * @description go View 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_goView = async function () {
    const sbmOptions = {
        id: "tx_goView",
        method: "post",
        action: "/info/notice.do?method=noticeView",
        ref: "dma_goViewReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_downloadFile
 * @description download File 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_downloadFile = async function (action) {
    try { return await $c.data.downFile(action ?? "/info/noticeDownload.do", "", ($c.util.getComponent("dma_downloadFileReq") ? $c.util.getComponent("dma_downloadFileReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function () {
    $c.util.getComponent("dma_goSearchReq").set("pageIndex", "1");
    await scwin.tx_goSearch();
};

/**
 * @method
 * @name goSearch2
 * @description go Search2 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch2 = async function () {
    await scwin.tx_goSearch2();
};

/**
 * @method
 * @name goView
 * @description go View 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goView = async function (id) {
    $c.util.getComponent('dma_goSearchReq').set('contnId', id);
    await scwin.tx_goView();
};

/**
 * @method
 * @name downloadFile
 * @description download File 처리
 * @param {*} contn_id contn_id
 * @param {*} attach_file_no attach_file_no
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.downloadFile = async function (contn_id, attach_file_no) {
    $c.util.getComponent("dma_downloadFileReq").set("method", 'noticeDownload');
    $c.util.getComponent("dma_goSearchReq").set("contnId", contn_id);
    $c.util.getComponent('dma_downloadFileReq').set('attachFileNo', attach_file_no);
    await scwin.tx_downloadFile('/info/noticeDownload.do');
};
